import pandas as pd, re
from collections import Counter

def top_levels(fn):
    df=pd.read_csv('/root/data/'+fn)
    tops=[]
    for p in df['category_path'].astype(str):
        top=p.split('>')[0].strip()
        tops.append(top)
    return Counter(tops)

for fn in ['amazon_product_categories.csv','fb_product_categories.csv','google_shopping_product_categories.csv']:
    c=top_levels(fn)
    print(fn, len(c))
    print(c.most_common(10))
